<?php
require_once __DIR__.'/includes/bootstrap.php'; require_admin(); $notice=''; $error='';
if(is_post()){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'requested';if(!in_array($status,['requested','approved','rejected'],true)){ $error='Invalid status.';} elseif(!$db){$error='Database unavailable.';} else{try{$db->beginTransaction();$st=$db->prepare('SELECT * FROM refunds WHERE id=? FOR UPDATE');$st->execute([$id]);$r=$st->fetch();if(!$r)throw new RuntimeException('Refund request not found.');if($r['status']!=='requested')throw new RuntimeException('This refund has already been processed.');$db->prepare('UPDATE refunds SET status=?,admin_note=? WHERE id=?')->execute([$status,trim($_POST['admin_note']??''),$id]);if($status==='approved'){$db->prepare('UPDATE users SET account_balance=account_balance+? WHERE id=?')->execute([$r['amount'],$r['user_id']]);$db->prepare('INSERT INTO balance_transactions(user_id,type,amount,reference,status) VALUES(?,?,?,?,?)')->execute([$r['user_id'],'refund_credit',$r['amount'],'Refund #'.$id,'approved']);$db->prepare("UPDATE orders SET status='refunded' WHERE id=?")->execute([$r['order_id']]);$db->prepare("UPDATE invoices SET status='credited' WHERE order_id=?")->execute([$r['order_id']]);}$db->commit();$notice='Refund request processed.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}}
$rows=$db?$db->query('SELECT r.*,o.order_number,u.full_name,u.email FROM refunds r LEFT JOIN orders o ON o.id=r.order_id LEFT JOIN users u ON u.id=r.user_id ORDER BY r.id DESC')->fetchAll():[];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Refunds — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="admin-page"><div class="portal-welcome"><div><span class="eyebrow mint">ADMIN</span><h1>Refund Requests</h1><p>Approve eligible refunds as WDH account-balance credit.</p></div></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="admin-table"><?php if(!$rows):?><div class="empty">No refund requests.</div><?php else:foreach($rows as $r):?><form method="post" class="admin-row"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><div><strong><?=e($r['order_number'])?></strong><small><?=e($r['full_name'])?> · <?=e($r['email'])?></small></div><strong><?=money($r['amount'],'BDT')?></strong><small><?=e($r['reason'])?></small><select name="status" <?=$r['status']!=='requested'?'disabled':''?>><option <?=$r['status']==='requested'?'selected':''?>>requested</option><option <?=$r['status']==='approved'?'selected':''?>>approved</option><option <?=$r['status']==='rejected'?'selected':''?>>rejected</option></select><input name="admin_note" placeholder="Admin note"><button class="btn primary small" <?=$r['status']!=='requested'?'disabled':''?>>Save</button></form><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
